# Dataset statistics table (executed by make_tables.py; uses its helpers J, w, placeholder, pct, num, macro)
d = J('trackD/dataset_stats.json')
if d is None: placeholder('dataset', 'tab:dataset', 'dataset statistics')
else:
    c = d['camera']; s = d['selected_pairs_labels']; a = d['all_candidate_pairs_labels']; sc = d['screening']
    def r(lab, q, unit, dd=1): return f'{lab} & {q["min"]:.{dd}f} & {q["p5"]:.{dd}f} & {q["p50"]:.{dd}f} & {q["p95"]:.{dd}f} & {q["max"]:.{dd}f} & {unit} \\\\'
    B = ['\\multicolumn{7}{@{}l}{\\emph{Cameras} (' + f'{d["cameras"]:,}'.replace(',', '{,}') + ')}\\\\', r('Height above terrain', c['height_above_terrain_m'], 'm'), r('Tilt $\\psi$', c['tilt_deg'], '$^\\circ$'), r('Horizontal offset from the anchor', c['camera_horizontal_offset_from_anchor_m'], 'm'),
         '\\midrule\\multicolumn{7}{@{}l}{\\emph{Selected pairs} (' + f'{d["selected_pairs"]:,}'.replace(',', '{,}') + ')}\\\\', r('Baseline $\\|\\dpv\\|$', s['dist'], 'm'), r('$|\\Delta x|$', s['abs_x'], 'm'), r('$|\\Delta y|$', s['abs_y'], 'm'), r('$|\\Delta z|$', s['abs_z'], 'm'), r('$|\\dpsi|$', s['abs_tilt'], '$^\\circ$'), r('$|\\dth|$', s['abs_heading'], '$^\\circ$'),
         '\\midrule\\multicolumn{7}{@{}l}{\\emph{All candidate pairs} (' + f'{d["candidates_vs_selected"]["candidates"]:,}'.replace(',', '{,}') + ')}\\\\', r('Baseline $\\|\\dpv\\|$', a['dist'], 'm'), r('$|\\Delta x|$', a['abs_x'], 'm'), r('$|\\Delta z|$', a['abs_z'], 'm'), r('$|\\dpsi|$', a['abs_tilt'], '$^\\circ$'), r('$|\\dth|$', a['abs_heading'], '$^\\circ$'),
         '\\midrule\\multicolumn{7}{@{}l}{\\emph{Screening statistics stored with the selected pairs}}\\\\', r('SIFT matches', sc['matches'], '', 0), r('Inliers', sc['inliers'], '', 0), r('Inlier ratio', sc['inlier_ratio'], '', 2), r('Hull fraction of the inliers', sc['hull_fraction'], '', 2), r('Occupied cells of a $4{\\times}4$ grid', sc['grid_cells'], '', 0)]
    w('dataset', '\\begin{table}[t]\n\\centering\n\\caption{\\textbf{Statistics of PairUAV} over ' + f'{d["buildings"]:,}'.replace(',', '{,}') + ' buildings.}\n\\label{tab:dataset}\n\\footnotesize\n\\setlength{\\tabcolsep}{3.5pt}\n\\begin{tabular}{@{}lrrrrrl@{}}\n\\toprule\n& min & 5\\% & 50\\% & 95\\% & max & \\\\\n\\midrule\n' + '\n'.join(B) + '\n\\bottomrule\n\\end{tabular}\n\\end{table}')
    h = c['height_above_terrain_m']; macro('dsBuildings', f'{d["buildings"]:,}'.replace(',', '{,}')); macro('dsCameras', f'{d["cameras"]:,}'.replace(',', '{,}')); macro('dsPairs', f'{d["selected_pairs"]:,}'.replace(',', '{,}')); macro('dsCand', f'{d["candidate_directed_pairs_per_building"]:,}'.replace(',', '{,}'))
    macro('dsHmin', f'{h["min"]:.1f}'); macro('dsHmax', f'{h["max"]:.1f}'); macro('dsHmean', f'{h["mean"]:.0f}'); macro('dsHstd', f'{h["std"]:.1f}'); macro('dsSelFrac', pct(d['selected_fraction'])); macro('dsInRange', pct(d['candidates_vs_selected']['fraction_of_all_candidates_inside_all_five_ranges']))
    macro('dsSelOfInRange', pct(d['candidates_vs_selected']['selected_over_candidates_inside_all_ranges'])); macro('dsDistMed', f'{s["dist"]["p50"]:.1f}'); macro('dsDistPone', f'{s["dist"]["p1"]:.1f}'); macro('dsDistMax', f'{s["dist"]["max"]:.1f}'); macro('dsDistPninenine', f'{s["dist"]["p99"]:.1f}')
    macro('dsMinInl', f'{sc["minima"]["inliers"]:.0f}'); macro('dsMinCells', f'{sc["minima"]["grid_cells"]:.0f}'); macro('dsInlMed', f'{sc["inliers"]["p50"]:.0f}'); macro('dsInlRatioMed', f'{sc["inlier_ratio"]["p50"]:.2f}'); macro('dsInlLtHundred', pct(sc['share_below']['inliers_lt_100']))
    macro('dsGroups', str(d['balancing']['groups'])); macro('dsXYinRange', pct(d['candidates_vs_selected']['fraction_of_all_candidates_inside_range_per_component']['x']))
